import geometry;

for(int i = 0; i<12; ++i){
for(int j = 0; j<6; ++j){
dot((i,j));
}
}

draw((0.5,-0.5)--(0.5,5.5),dotted);
draw((3,1)--(0,1)--(0,0)--(3,0),red+dotted); 
draw((3,1)--(3,0),red); 
