     &= \frac{(r-p)(2pqr-pr^2-q^2p)}{q^2-pr}
     &= \frac{p(r-p)(r-q)^2}{pr-q^2}.
 \end{align*}
 Therefore,
 \begin{align*}
 \frac{1+r^2}{q+r}&=\frac{p(r-p)(r-q)}{pr-q^2}
 pr-q^2+pr^3-q^2r^2 &= pr^2q+pr^3-p^2rq-p^2r^2-pq^2r-pqr^2+p^2q^2+p^2qr
