// Center of the entire 8x8 board (center of square (4.5, 4.5))
pair O = (4.5, 4.5);

// Draw the chessboard grid
for (int i = 1; i <= 8; ++i) {
    for (int j = 1; j <= 8; ++j) {
        draw(box((i-0.5, j-0.5), (i+0.5, j+0.5)));
    }
}

// Draw the path with color coding based on distance from board center O
pen greenPen = blue + linewidth(1.5);
pen bluePen = red + linewidth(1.5);

for (int i = 0; i < tour.length - 1; ++i) {
    pair current = tour[i];
    pair next = tour[i+1];

    // Convert cell coordinates to center coordinates
    pair centerCurrent = (current.x, current.y);
    pair centerNext = (next.x, next.y);

    // Calculate distances from board center O
    real distCurrent = length(centerCurrent - O);
    real distNext = length(centerNext - O);

