    {(2,2), (1,1)},  // (2,2) -> (1,1) (not reversed)
    {(1,3), (1,2)},  // (1,2) -> (1,3) REVERSED
    {(1,4), (1,3)},  // (1,3) -> (1,4) REVERSED
    {(3,1), (2,1)},  // (2,1) -> (3,1) REVERSED
    {(4,1), (3,1)}   // (3,1) -> (4,1) REVERSED
};

// Draw the 4x4 grid (with (1,1) at top left)
for (int i = 1; i <= 4; ++i) {
    for (int j = 1; j <= 4; ++j) {
        // Transform: (x,y) -> (x, 5-y) to flip vertically
        draw(box((i-0.5, 5-j-0.5), (i+0.5, 5-j+0.5)), black+0.7pt);
    }
}

// Draw the directed arrows with cleaner appearance
for (int i = 0; i < arrows.length; ++i) {
    pair start = arrows[i][0];
    pair end = arrows[i][1];

    // Transform: (x,y) -> (x, 5-y) to flip vertically
    pair centerStart = (start.x, 5-start.y);
    pair centerEnd = (end.x, 5-end.y);

