Let  $x_{n+1}=\dots=x_{2^t}=0\ (2^t\ge n),\ S=\sum_{i=1}^{2^t}x_i$  and  $A_m=\sum_{\text{length blocks }2^m}\Big(\sum_{i\in \text{block}}x_i\Big)^2$ , for  $m=0,1,\dots,t$ \begin{align*}
\sum_{1\le i<j\le n}\frac{x_ix_j}{2^{\nu_2(j-i)}} 
&= \sum_{m=0}^{t-1}2^{-m}\!\!\sum_{\substack{\text{block }B\ \text{for }2^{m+1} B=L\sqcup R}}\ \sum_{i\in L,\,j\in R}\! x_ix_j = \sum_{m=0}^{t-1}2^{-m}\!\!\sum_{B=L\sqcup R}\! \Big(\sum_{i\in L}x_i\Big)\Big(\sum_{j\in R}x_j\Big) 
&= \frac{1}{2}\sum_{m=0}^{t-1}2^{-m}\!\!\sum_{B=L\sqcup R}\!\Bigg[\Big(\sum_{i\in B}x_i\Big)^2 - \Big(\sum_{i\in L}x_i\Big)^2 - \Big(\sum_{i\in R}x_i\Big)^2\Bigg] = \frac{1}{2}\sum_{m=0}^{t-1}2^{-m}(A_{m+1} - A_m) 
&= \frac{1}{2}\Bigg(\sum_{m=0}^{t-1}2^{-m}A_{m+1} - \sum_{m=0}^{t-1}2^{-m}A_m\Bigg) \le \frac{1}{3}\sum_{m=0}^{t-1}2^{-m}A_{m+1} \le \frac{1}{3}\sum_{m=0}^{t-1}2^{-m}\cdot 2A_m 
&\Rightarrow \sum_{1\le i<j\le n}\frac{x_ix_j}{2^{\nu_2(j-i)}}\le \frac{1}{3}\cdot\frac{1}{2}\Bigg(\sum_{m=0}^{t-1}2^{-m}A_{m+1} + \sum_{m=0}^{t-1}2^{-m}A_m\Bigg) = \frac{1}{3}\cdot\frac{1}{2}\sum_{m=0}^{t-1}2^{-m}\Big(A_{m+1} + A_m\Big) 
&\le \frac{1}{3}\cdot\frac{1}{2}\sum_{m=0}^{t-1}2^{-m}\big(2A_{m+1}\big) = \frac{1}{3}\sum_{m=0}^{t-1}2^{-m}A_{m+1} \le \frac{1}{3}\sum_{m=0}^{t-1}2^{-m}A_t
&=\frac{1}{3}\Big(2 - 2^{-(t-1)}\Big)A_t - \frac{1}{3}\Big(1 - 2^{-(t-1)}\Big)A_t = \frac{1}{3}A_t = \frac{1}{3}\Bigg(\sum_{i=1}^{2^t}x_i\Bigg)^2= \frac{1}{3}\Bigg(\sum_{i=1}^{n}x_i\Bigg)^2
\end{align*}

