q & 0 & 1 
1 - \ell & d - \ell q & d - q 
(d - \ell q)(1 - \ell) & (d - \ell q)(d - q) & (1 - \ell)^2 + (d - q)^2
\end{vmatrix} 
&= \text{stuff} \cdot (q((d - \ell q)((1 - \ell)^2 + (d - q)^2) - (d - q)^2 (d - \ell q)) + ((1 - \ell)(d - \ell q)(d - q) - (d - \ell q)^2 (1 - \ell))) 
