\[a^2k(1+t)(1+t-kt)+k(-b^2t(1+t)+a^2k)-c^2(1+t)(1+t-kt)\]
\[+((-b^2t(1+t)+a^2k)+(b^2)(1+t)(1+t-kt)-k(-b^2t(1+t)+a^2k))\cdot(1+t)=0.\]
This has constant term of 
\[c^2(1+t)^2-b^2t(1+t)^2+b^2(1+t)^3=(b^2+c^2)(1+t)^2,\]
and  $k^2$  term of 
\[-a^2t(1+t)+a^2-a^2(1+t)=-a^2t(2+t),\]
