pair M=extension(T,Z,X,X+rotate(90)*(Y-X));
pair N=extension(Y,Z,X,X+rotate(90)*(T-X));

draw(X--Y--Z--T--cycle); draw(X--Z); draw(Y--T); draw (X--M--N--cycle);
