[asy]
import geometry;
import graph;

real markscalefactor=0.03;

size(10cm);
defaultpen(fontsize(10pt));

pair foot(pair from1, pair to1, pair to2) {
  return extension(rotate(90,to1)*to2-to1+from1,from1,to1,to2);
}

path anglemark(pair A, pair B, pair C, real t=8 ... real[] s){
    pair M,N,P[],Q[];
    path mark;
    int n=s.length;
    M=t*markscalefactor*unit(A-B)+B;
    N=t*markscalefactor*unit(C-B)+B;
    for (int i=0; i<n; ++i)
    {
        P[i]=s[i]*markscalefactor*unit(A-B)+B;
        Q[i]=s[i]*markscalefactor*unit(C-B)+B;
    }
    mark=arc(B,M,N);
    for (int i=0; i<n; ++i)
    {
        if (i%2==0)
        {
            mark=mark--reverse(arc(B,P[i],Q[i]));
        }
        else
        {
            mark=mark--arc(B,P[i],Q[i]);
        }
    }
    if (n%2==0 && n!=0)
    mark=(mark--B--P[n-1]);
    else if (n!=0)
    mark=(mark--B--Q[n-1]);
    else mark=(mark--B--cycle);
    return mark;
}

pair A = (-0.5,2);
