  (1,1), (1,2), (2,1), (2,2)
};

// Fill light gray cells
for (pair p : lightGray) {
  fill((p.x,p.y)--(p.x+1,p.y)--(p.x+1,p.y+1)--(p.x,p.y+1)--cycle, gray);
}

// Fill dark gray cells
for (pair p : darkGray) {
  fill((p.x,p.y)--(p.x+1,p.y)--(p.x+1,p.y+1)--(p.x,p.y+1)--cycle, 0.3*gray);
}

// Label white squares with "A"
for (int x = 0; x < n; ++x) {
  for (int y = 0; y < n; ++y) {
    pair p = (x, y);
    bool isShaded = false;
    for (pair s : lightGray) {
      if (p == s) { isShaded = true; break; }
    }
    for (pair s : darkGray) {
      if (p == s) { isShaded = true; break; }
